250	      pre: [["t-dim", "[upshift] run 20261010-173515-python-3.12"]],
251	      ok: "[upshift] OK: 26 passing, 0 new failures. Report: UPSHIFT_REPORT.md",
252	    },
253	  ];
254	
255	  const term = document.getElementById("term");
256	  const steps = [...document.querySelectorAll("#pipe li")];
257	  const reduced = matchMedia("(prefers-reduced-motion: reduce)").matches;
258	  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
259	
260	  const setStage = (i) => steps.forEach((li, j) => {
261	    li.classList.toggle("done", j < i);
262	    li.classList.toggle("on", j === i);
263	  });
264	
265	  const line = (cls, text) => {
266	    const el = document.createElement("div");
267	    el.className = cls;
268	    el.textContent = text;
269	    term.appendChild(el);
270	    return el;
271	  };
272	
273	  const cursor = document.createElement("span");
274	  cursor.className = "cursor";
275	
276	  // Reduced motion: show one finished run and a completed pipeline.
277	  if (reduced) {
278	    const run = RUNS[0];
279	    line("t-cmd", run.cmd);
280	    run.pre.forEach(([c, t]) => line(c, t));
281	    STAGES.forEach((s) => line("t-done", `[upshift] ${s} done`));
282	    line("t-ok", run.ok);
283	    setStage(STAGES.length);
284	  } else {
285	    const typeCmd = async (text) => {
286	      const el = line("t-cmd", "");
287	      el.appendChild(cursor);
288	      for (const ch of text) {
289	        cursor.before(ch);
290	        await sleep(28 + Math.random() * 40);
291	      }
292	      await sleep(350);
293	      cursor.remove();
294	    };
295	
296	    const play = async () => {
297	      for (;;) {
298	        for (const run of RUNS) {
299	          term.textContent = "";
300	          setStage(-1);
301	          await typeCmd(run.cmd);
302	          for (const [c, t] of run.pre) { line(c, t); await sleep(260); }
303	          for (let i = 0; i < STAGES.length; i++) {
304	            setStage(i);
305	            await sleep(STAGES[i] === "fix" || STAGES[i] === "research" ? 1100 : 550);
306	            line("t-done", `[upshift] ${STAGES[i]} done`);
307	          }
308	          setStage(STAGES.length);
309	          line("t-ok", run.ok);
310	          const prompt = line("t-cmd", "");
311	          prompt.appendChild(cursor);
312	          await sleep(3200);
313	        }
314	      }
315	    };
316	
317	    let started = false;
318	    new IntersectionObserver((entries, obs) => {
319	      if (entries[0].isIntersecting && !started) { started = true; obs.disconnect(); play(); }
320	    }).observe(term);
321	  }
322	
323	  // Fade sections in as they scroll into view.
324	  const io = new IntersectionObserver((entries) => entries.forEach((e) => {
325	    if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
326	  }), { threshold: 0.12 });
327	  document.querySelectorAll(".reveal").forEach((el) => io.observe(el));
328	
329	  // Copy buttons copy the command without the trailing comment.
330	  document.querySelectorAll(".copy").forEach((btn) => btn.addEventListener("click", async () => {
331	    const pre = btn.previousElementSibling.cloneNode(true);
332	    pre.querySelectorAll(".c").forEach((c) => c.remove());
333	    try {
334	      await navigator.clipboard.writeText(pre.textContent.trim());
335	      btn.textContent = "copied"; btn.classList.add("ok");
336	    } catch { btn.textContent = "failed"; }
337	    setTimeout(() => { btn.textContent = "copy"; btn.classList.remove("ok"); }, 1400);
338	  }));
