428	  const update = () => {
429	    const r = story.getBoundingClientRect();
430	    p = clamp(-r.top / (r.height - innerHeight));
431	
432	    scenes.forEach((s, i) => {
433	      const a = +s.dataset.in, b = +s.dataset.out;
434	      const fadeIn = i === 0 ? 1 : span(p, a, a + .04);
435	      const o = fadeIn * (1 - span(p, b - .04, b));
436	      s.style.opacity = o;
