438	      s.classList.toggle("live", o > .5);
439	    });
440	
441	    // bump: baseline green, roll the version, then the suite breaks
442	    const t = span(p, .19, .37);
443	    rolls.forEach((roll, i) => { roll.style.transform = `translateY(${-ease(span(t, .25 + i * .04, .55 + i * .04))}em)`; });
