472	
473	  // Ridgeline mountains: grow as the story goes up, shake red when the build breaks, settle green when it passes.
474	  const canvas = document.getElementById("ridges");
475	  const ctx = canvas.getContext("2d");
476	  let W = 0, H = 0;
477	  const resize = () => {
478	    const dpr = Math.min(devicePixelRatio || 1, 2);
479	    W = canvas.width = canvas.clientWidth * dpr;
480	    H = canvas.height = canvas.clientHeight * dpr;
481	  };
