487	    const green = span(p, .66, .72) * (1 - span(p, .84, .9));
488	    const col = mix(mix(YEL, RED, red), GRN, green);
489	    const rise = .3 + .7 * ease(p);
490	    const lines = 24, pts = 96, narrow = W < 900;
491	    ctx.clearRect(0, 0, W, H);
492	    ctx.lineWidth = Math.max(1, W / 1400);
493	    for (let i = 0; i < lines; i++) {
494	      const d = i / (lines - 1);
495	      const y0 = H * (.5 + d * .56);
