501	        const n = Math.sin(x * 13 + i * 1.7 + time * .0005) * .5 + Math.sin(x * 29 - i * .9 + time * .0011) * .3;
502	        const jitter = red * Math.sin(x * 90 + time * .03 + i) * .5;
503	        const y = y0 - H * .3 * rise * peak * (.55 + .45 * Math.sin(i * .7 + 1)) - (n + jitter) * H * .012 * (.4 + peak);
504	        j ? ctx.lineTo(x * W, y) : ctx.moveTo(x * W, y);
